package edu.sc.servicedemo; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import org.junit.jupiter.api.*; class ApiTest { @Test void completingRequestChangesStatus(){RequestRepo repo=mock(RequestRepo.class);ServiceRequest request=new ServiceRequest();request.id=1L;request.status="OPEN";when(repo.findById(1L)).thenReturn(java.util.Optional.of(request));Api api=new Api(repo,mock(UserRepo.class));assertEquals("COMPLETE",api.complete(1L).status());verify(repo).save(request);} }
